/bin/bash -lc "set -o pipefail
q='Suresh Gyan Vihar University Jaipur official website'
url=\"https://www.google.com/search?q="'$(printf '"'%s' \""'$q" | jq -sRr @uri)"
curl --insecure --fail --silent --show-error --location --max-time 30 -A '"'Mozilla/5.0' \""'$url" > "$TMPDIR/sgvu-google-1.html"
rg -o '"'https?://["'^&"<> ]+'"' \""'$TMPDIR/sgvu-google-1.html" | sed '"'s/\\\\u003d/=/g;s/\\\\u0026/\\&/g' | head -30
python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]; self.t=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='a' and d.get('href'): self.links.append(d['href'])
    def handle_data(self,d): self.t.append(d)
p=P(); p.feed(Path('/Users/d111879/Documents/Project/DEMO/Student/Student_mobile/sapp/research/agent_runs/rajasthan-candidate-wave-20260927-wave-001/tmp/sgvu-google-1.html').read_text(errors='ignore'))
for x in p.links:
    if 'url?q=' in x or x.startswith('http'):
        print(x[:400])
PY"

