/bin/bash -lc "q='Suresh Gyan Vihar University Jaipur official website'
url=\"https://www.bing.com/search?q="'$(printf '"'%s' \""'$q" | jq -sRr @uri)"
out="$TMPDIR/sgvu-bing-1.html"
curl --insecure --fail --silent --show-error --location --max-time 30 -A '"'Mozilla/5.0' \""'$url" -o "$out"
python3 - "$out" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]; self.data=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='a' and d.get('href'): self.links.append((d.get('href'), ''))
    def handle_data(self,d):
        if d.strip(): self.data.append(d.strip())
p=P(); p.feed(Path(sys.argv[1]).read_text(errors='ignore'))
for h,_ in p.links:
    if h.startswith('http'):
        print(h)
print('TEXT')
print(' | '.join(p.data[:120]))
PY"

