url=\"https://html.duckduckgo.com/html/?q="'$(printf '"'%s' \""'$q" | jq -sRr @uri)"
out="$TMPDIR/sgvu-ddg-1.html"
curl --insecure --fail --silent --show-error --location --max-time 30 -A '"'Mozilla/5.0' \""'$url" -o "$out"
python3 - "$out" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.href=None; self.text=[]; self.rows=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='a' and 'result__a' in d.get('class',''): self.href=d.get('href'); self.text=[]
    def handle_data(self,d):
        if self.href: self.text.append(d.strip())
    def handle_endtag(self,t):
        if t=='a' and self.href:
            self.rows.append((self.href,' '.join(x for x in self.text if x))); self.href=None
p=P(); p.feed(Path(sys.argv[1]).read_text(errors='ignore'))
for h,t in p.rows: print(t,'\\t',h)
PY"

